def settle(debts, start):
    while start < len(debts) and debts[start] == 0:
        start += 1
    if start == len(debts):
        return 0
    best = 10 ** 9
    seen = set()
    for j in range(start + 1, len(debts)):
        if debts[j] * debts[start] < 0 and debts[j] not in seen:
            seen.add(debts[j])                  # partners with the same balance are the same choice
            debts[j] += debts[start]            # one payment settles the first person
            best = min(best, 1 + settle(debts, start + 1))
            debts[j] -= debts[start]
    return best

